Use the 
```
woocommerce_bookings_importer_timestamp_mode
```

 filter to choose how imported datetime offsets should be interpreted. The default mode, 
```
preserve_wall_clock
```

, keeps the same clock reading from the CSV regardless of timezone differences. The snippet below switches that default to 
```
preserve_instant
```

, which shifts the imported value to the destination site’s local equivalent of the same absolute moment.

```
add_filter(
	'woocommerce_bookings_importer_timestamp_mode',
	function ( string $mode ): string {
		if ( 'preserve_wall_clock' === $mode ) {
			return 'preserve_instant';
		}

		return $mode;
	}
);
```

Use the 
```
woocommerce_bookings_import_inserted_booking_object
```

 action to run follow-up logic after the importer has saved a booking. At this point the booking object has already been created or updated, so the hook is useful for logging, notifications, or syncing related systems. The snippet below writes a WooCommerce log entry that includes the booking ID, whether it was created or updated, and how many mapped fields were processed.

```
add_action(
	'woocommerce_bookings_import_inserted_booking_object',
	function ( WC_Booking $booking, array $data, bool $updating ): void {
		$logger = wc_get_logger();
		$action = $updating ? 'updated' : 'created';

		$logger->info(
			sprintf(
				'Booking %1$d was %2$s from a CSV import with %3$d mapped fields.',
				$booking->get_id(),
				$action,
				count( $data )
			),
			array( 'source' => 'bookings-import' )
		);
	},
	10,
	3
);
```

Use the 
```
woocommerce_bookings_import_pre_save_booking_object
```

 filter to change the 
```
WC_Booking
```

 object after CSV data has been applied but before the importer saves it. This is useful for adding custom metadata or normalizing values that are not part of the default import fields. The snippet below records who imported a new booking and stores a source CSV ID when that value is present.

```
add_filter(
	'woocommerce_bookings_import_pre_save_booking_object',
	function ( WC_Booking $booking, array $data, bool $updating ): WC_Booking {
		if ( ! $updating ) {
			$booking->update_meta_data( '_imported_by', get_current_user_id() );
		}

		if ( isset( $data['id'] ) ) {
			$booking->update_meta_data( '_source_csv_id', wc_clean( $data['id'] ) );
		}

		return $booking;
	},
	10,
	3
);
```

Use the 
```
woocommerce_bookings_csv_import_mapped_columns
```

 filter after automatic mapping has finished and the importer has resolved the selected headers. This is the right place to make final mapping adjustments that depend on the raw uploaded headers. The snippet below maps 
```
My Custom Column
```

 to a custom internal field when that header appears in the CSV.

```
add_filter(
	'woocommerce_bookings_csv_import_mapped_columns',
	function ( array $headers, array $raw_headers ): array {
		if ( in_array( 'My Custom Column', $raw_headers, true ) ) {
			$headers['My Custom Column'] = 'my_custom_field';
		}

		return $headers;
	},
	10,
	2
);
```

Use the 
```
woocommerce_bookings_csv_import_mapping_default_columns
```

 filter to adjust the importer’s automatic CSV header mapping. This is helpful when a source system exports a familiar value under a custom column label. The snippet below maps a header named 
```
My Start Column
```

 to the internal 
```
start
```

 field only when that header exists in the uploaded CSV.

```
add_filter(
	'woocommerce_bookings_csv_import_mapping_default_columns',
	function ( array $columns, array $raw_headers ): array {
		if ( in_array( 'My Start Column', $raw_headers, true ) ) {
			$columns['My Start Column'] = 'start';
		}

		return $columns;
	},
	10,
	2
);
```

Use the 
```
woocommerce_bookings_import_batch_size
```

 filter to change how many rows the importer processes in each AJAX batch. Larger batches can finish faster, but they also use more memory and may be more likely to time out on constrained hosts. The snippet below sets the batch size to 50 while preserving the incoming value when it already matches that target.

```
add_filter(
	'woocommerce_bookings_import_batch_size',
	function ( int $size ): int {
		if ( 50 !== $size ) {
			return 50;
		}

		return $size;
	}
);
```

Use the 
```
woocommerce_bookings_csv_importer_args
```

 filter to change the arguments passed into the importer constructor. This is useful when the default importer class is still correct, but one runtime option needs adjustment. The snippet below increases the number of parsed lines for the default importer class while leaving arguments unchanged for other importer classes.

```
add_filter(
	'woocommerce_bookings_csv_importer_args',
	function ( array $args, string $importer_class ): array {
		if ( WC_Bookings_Importer::class === $importer_class ) {
			// Process 50 rows per batch instead of the default 30.
			$args['lines'] = 50;
		}

		return $args;
	},
	10,
	2
);
```

Use the 
```
woocommerce_bookings_csv_importer_class
```

 filter when a customization needs to replace the CSV importer with a class that extends 
```
WC_Bookings_Importer
```

. This is a deeper extension point than changing mappings or batch size, so the replacement class should preserve the importer contract. The snippet below returns a custom importer class only when that class is available, otherwise it leaves the default importer in place.

```
add_filter(
	'woocommerce_bookings_csv_importer_class',
	function ( string $importer_class ): string {
		if ( class_exists( My_Custom_Bookings_Importer::class ) ) {
			return My_Custom_Bookings_Importer::class;
		}

		return $importer_class;
	}
);
```

Use the 
```
woocommerce_bookings_export_skip_meta_keys
```

 filter when the custom meta export should omit plugin-owned or internal fields. Core booking data-store keys, 
```
_edit_lock
```

, and 
```
_edit_last
```

 are already excluded. The snippet below adds another private meta key to the skipped list for confirmed bookings and returns a de-duplicated key list.

```
add_filter(
	'woocommerce_bookings_export_skip_meta_keys',
	function ( array $keys, WC_Booking $booking ): array {
		if ( 'confirmed' === $booking->get_status() ) {
			$keys[] = '_my_plugin_internal_key';
		}

		return array_unique( $keys );
	},
	10,
	2
);
```

Use the 
```
woocommerce_bookings_export_statuses
```

 filter to control which booking post statuses are included in the export. By default, Bookings includes the statuses that are visible and relevant to admins, customers, and cancellation flows. The snippet below narrows the allowed set to confirmed and paid bookings, while still intersecting with the statuses Bookings made available.

```
add_filter(
	'woocommerce_bookings_export_statuses',
	function ( array $statuses ): array {
		$allowed_statuses = array_intersect( $statuses, array( 'confirmed', 'paid' ) );

		return array_values( $allowed_statuses );
	}
);
```

Use the 
```
woocommerce_bookings_export_query_args
```

 filter to adjust the query arguments passed to 
```
WC_Booking_Data_Store::get_booking_ids_by()
```

. This lets a customization narrow or expand the bookings included before the export rows are built. The snippet below limits the export to bookings assigned to one resource ID, which can be adapted for resource-specific reporting.

```
add_filter(
	'woocommerce_bookings_export_query_args',
	function ( array $args ): array {
		// Only export bookings assigned to a specific resource.
		$args['object_id']   = array( 42 );
		$args['object_type'] = 'resource';

		return $args;
	}
);
```

Use the 
```
woocommerce_bookings_export_row_data
```

 filter when several columns need to be adjusted together before the CSV row is written. This is useful for row-level transformations, derived values, or normalizing values from multiple fields at the same time. The snippet below uppercases the exported status and adds the booking ID explicitly to the row data.

```
add_filter(
	'woocommerce_bookings_export_row_data',
	function ( array $row, WC_Booking $booking ): array {
		if ( isset( $row['status'] ) ) {
			$row['status'] = strtoupper( (string) $row['status'] );
		}

		$row['booking_id'] = $booking->get_id();

		return $row;
	},
	10,
	2
);
```

Use the 
```
woocommerce_bookings_export_column_{column_id}
```

 filter when one exported column needs custom output for each booking row. Replace 
```
{column_id}
```

 with the column key you want to control. The snippet below targets a custom field column, checks that the expected column is being processed, and falls back to the original value when no custom meta value is available.

```
add_filter(
	'woocommerce_bookings_export_column_my_custom_field',
	function ( string $value, WC_Booking $booking, string $column_id ): string {
		if ( 'my_custom_field' !== $column_id ) {
			return $value;
		}

		$custom_value = get_post_meta( $booking->get_id(), '_my_custom_field', true );

		if ( '' === $custom_value || ! is_scalar( $custom_value ) ) {
			return $value;
		}

		return (string) $custom_value;
	},
	10,
	3
);
```

Use the 
```
woocommerce_bookings_export_default_columns
```

 filter when the export needs a different set of columns than the defaults. The filter receives the full column map, where each key is the exported field ID and each value is the label shown in the generated CSV. The snippet below adds a custom column and removes the Google Calendar event ID column so the export matches a custom reporting format.

```
add_filter(
	'woocommerce_bookings_export_default_columns',
	function ( array $columns ): array {
		// Add a custom column to the export.
		$columns['my_custom_field'] = __( 'My Custom Field', 'my-plugin' );

		// Remove an existing column from the export.
		unset( $columns['google_calendar_event_id'] );

		return $columns;
	}
);
```

