premium
```

 Shipping Classes, use the following snippet:

```
add_filter( 'woocommerce_csp_package_item_quantity_count', 'wc_sw_csp_shipping_class_items_count', 10, 4 );

function wc_sw_csp_shipping_class_items_count( $total_quantity, $package, $data, $args ) {

	$restriction_type  = $args[ 'restriction_data' ][ 'restriction_id' ];
	$restriction_index = $args[ 'restriction_data' ][ 'index' ];
	$condition_index   = $data[ 'condition_index' ];

	if ( 'shipping_methods' == $restriction_type && 0 == $restriction_index && 0 == $condition_index ) {
		$total_quantity = 0;

		foreach ( $package[ 'contents' ] as $cart_item_key => $cart_item_data ) {

			$product_id     = $cart_item_data[ 'product_id' ];
			$product        = wc_get_product( $product_id );
			$shipping_class = $product->get_shipping_class();

			if ( in_array( $shipping_class, array( 'free', 'premium' ) ) ) {
				$total_quantity += $cart_item_data[ 'quantity' ];
			}
		}
	}

	return $total_quantity;
}
```

