 * @param  WC_Order  $order  Order object containing billing information.
 */
function woo_support_prevent_gift_card_email_mismatch( $order ) {

	if ( ! function_exists( 'WC_GC' ) ) {
		return;
	}

	$giftcards = WC_GC()->giftcards->get();
	if ( empty( $giftcards ) ) {
		return;
	}

	$billing_email = $order->get_billing_email();
	if ( ! $billing_email ) {
		return;
