	$billing_email = $order->get_billing_email();
	if ( ! $billing_email ) {
		return;
	}

	$has_mismatch = false;
	foreach ( $giftcards as $giftcard_info ) {
		$giftcard = $giftcard_info['giftcard'];
		if ( $giftcard->get_id() ) {
			$giftcard_email = $giftcard->get_recipient();
			if ( $giftcard_email !== $billing_email ) {
