				WC_GC()->giftcards->remove_giftcard_from_session( $giftcard->get_id() );
				$has_mismatch = true;
			}
		}
	}

	if ( $has_mismatch ) {
		throw new Exception( __( 'Gift card email does not match user email.', 'woocommerce-gift-cards' ) );
	}
}
